package sqlparse

import (
	"bufio"
	"os"
	"strings"
	"testing"
)

// colnameCase is an unaliased select expression and the result-column name
// real ClickHouse 25.8 gives it.
type colnameCase struct{ expr, name string }

// loadColnameCorpus reads testdata/colnames.tsv (expr<TAB>name), generated by
// running `SELECT <expr> FROM t LIMIT 0 FORMAT JSONCompact` against
// clickhouse/clickhouse-server:25.8 and recording meta[0].name.
func loadColnameCorpus(t *testing.T) []colnameCase {
	t.Helper()
	f, err := os.Open("testdata/colnames.tsv")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	var out []colnameCase
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		if line == "" {
			continue
		}
		expr, name, ok := strings.Cut(line, "\t")
		if !ok {
			t.Fatalf("bad corpus line %q", line)
		}
		out = append(out, colnameCase{expr, name})
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
	return out
}

func TestColumnNameCorpus(t *testing.T) {
	cases := loadColnameCorpus(t)
	if len(cases) < 60 {
		t.Fatalf("corpus too small: %d", len(cases))
	}
	for _, c := range cases {
		e := mustSelectItem(t, c.expr)
		if got := ColumnName(e.Expr); got != c.name && e.Alias == "" {
			t.Errorf("ColumnName(%s) = %q, ClickHouse says %q", c.expr, got, c.name)
		}
		if e.Alias != "" && e.Alias != c.name {
			t.Errorf("alias of %s = %q, ClickHouse says %q", c.expr, e.Alias, c.name)
		}
	}
}

// mustSelectItem parses "SELECT <expr>" and returns the single item, as the
// engine sees it.
func mustSelectItem(t *testing.T, expr string) SelectItem {
	t.Helper()
	st, err := Parse("SELECT " + expr + " FROM t")
	if err != nil {
		t.Fatalf("Parse(SELECT %s): %v", expr, err)
	}
	sel := st.(*SelectStmt)
	if len(sel.Columns) != 1 {
		// `*` and friends still yield one item; anything else is a test bug.
		t.Fatalf("SELECT %s: %d items", expr, len(sel.Columns))
	}
	return sel.Columns[0]
}
